"""
Content scanning for uploaded distribution files.

This module compiles a set of YARA rules (see ``scanner_rules/``) and uses them
to inspect the contents of uploaded archives for disallowed content, such as
PyArmor-encrypted payloads.

The scanner is intentionally *fail-open*: any error encountered while compiling
rules or scanning content results in "no match" rather than an exception. A
scanning failure must never block a legitimate upload.
"""

from __future__ import annotations

import glob
import os.path

from dataclasses import dataclass
from typing import Iterable, Optional

import yara_x

# Maximum size (in bytes) of an individual archive member that will be scanned.
# Members larger than this are silently skipped.
_SCAN_MAX_FILE_SIZE = 32 * 1024 * 1024  # 32 MiB

# When the total accumulated size of the members being scanned exceeds this
# threshold, we scan each member individually rather than concatenating them
# into a single buffer. This keeps memory usage bounded and ensures matches are
# attributed to the correct member.
_BULK_SCAN_MAX_TOTAL = 64 * 1024 * 1024  # 64 MiB

# File extensions that are worth scanning inside an archive.
_SCANNABLE_EXTENSIONS = (".py", ".pyc", ".pyd", ".so")


@dataclass(frozen=True)
class YaraMatch:
    """A single YARA rule match found while scanning an archive member."""

    rule: str
    member: str
    message: str


def compile_rules(rules_dir=None) -> Optional[yara_x.Rules]:
    """
    Compile all ``*.yar`` files found in ``rules_dir``.

    Defaults to the built-in ``scanner_rules`` directory alongside this module.

    Returns ``None`` if there are no rule files, if any rule fails to compile,
    or if any other error occurs (fail-open).
    """
    if rules_dir is None:
        rules_dir = os.path.join(os.path.dirname(__file__), "scanner_rules")

    try:
        rule_files = sorted(glob.glob(os.path.join(rules_dir, "*.yar")))
        if not rule_files:
            return None

        compiler = yara_x.Compiler()
        for rule_file in rule_files:
            with open(rule_file, encoding="utf-8") as fp:
                compiler.add_source(fp.read(), origin=rule_file)
        return compiler.build()
    except Exception:
        # Fail-open: any problem compiling rules means we scan nothing.
        return None


def _get_rule_message(rule) -> str:
    """
    Extract the ``message`` metadata value from a matched YARA rule object.
    """
    for key, value in rule.metadata:
        if key == "message":
            return value
    return ""


def _match_from_rule(rule, member: str) -> YaraMatch:
    return YaraMatch(
        rule=rule.identifier,
        member=member,
        message=_get_rule_message(rule),
    )


