) -> Optional[YaraMatch]:
    """
    Scan an iterable of archive members for YARA rule matches.

    Each member is a ``(path, size, data)`` tuple. Members larger than
    ``_SCAN_MAX_FILE_SIZE`` are skipped. Returns a :class:`YaraMatch` for the
    first matching member, or ``None`` when nothing matches.

    Falls back to the module-level ``_rules`` when ``rules`` is not provided,
    and returns ``None`` when no rules are available.

    Scanning is fail-open: a :class:`yara_x.ScanError` results in ``None``.
    """
    if rules is None:
        rules = _rules
    if rules is None:
        return None

    # Materialize the members we're willing to scan, dropping anything that is
    # too large to bother with.
    scannable: list[tuple[str, bytes]] = [
